<template>
  <div class="mx-auto max-w-7xl">
    <UButton :to="portal ? '/portal/events' : '/events'" variant="ghost" icon="i-lucide-arrow-left" class="mb-4">All events</UButton>
    <USkeleton v-if="pending && !data" class="h-64" />
    <UAlert v-else-if="error" color="error" title="Event could not load" :description="error.data?.statusMessage || error.message" />
    <template v-else-if="data">
      <section class="mb-6 flex flex-wrap items-end justify-between gap-4"><div><div class="flex items-center gap-3"><p class="text-sm font-semibold text-primary">EVENT MANAGEMENT</p><UBadge :color="data.event.status === 'open' ? 'success' : 'neutral'">{{ data.event.status }}</UBadge></div><h2 class="mt-2 text-3xl font-semibold">{{ data.event.name }}</h2><p class="mt-2 text-sm text-slate-500">{{ data.event.startDate }} – {{ data.event.endDate }} · {{ data.event.venue }}</p></div><div class="flex gap-2"><UButton v-if="data.canManage" color="neutral" variant="outline" icon="i-lucide-settings" @click="() => { editingEvent = !editingEvent }">Settings</UButton><UButton v-if="canRegister" icon="i-lucide-user-plus" @click="openBooking()">Register</UButton></div></section>
      <EventEditor v-if="editingEvent" :initial="data.event" :currency="data.event.currency" class="mb-6" @saved="eventSaved" @cancel="editingEvent = false" />
      <div v-if="editingEvent && data.canManage && !data.bookings.length && !data.costs.length && !data.registrationRequests.length && !data.ledger.length" class="mb-6 flex items-center justify-between rounded-xl border border-red-200 p-4 text-sm dark:border-red-900"><span>Unused event? You can remove it permanently.</span><UButton color="error" variant="outline" :loading="deletingEvent" @click="deleteEvent">Delete event</UButton></div>
      <div class="mb-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard label="Reserved attendees" :value="`${data.occupancy.people}${data.event.capacity ? ` / ${data.event.capacity}` : ''}`" :description="`${data.occupancy.students} students · ${data.occupancy.parents} accompanying people`" icon="i-lucide-users" /><MetricCard label="Accommodation" :value="`${data.occupancy.beds}${data.event.bedCapacity ? ` / ${data.event.bedCapacity}` : ''}`" description="Beds requested" icon="i-lucide-bed-double" /><MetricCard v-if="data.event.transportProvided" label="Transport" :value="`${data.occupancy.outbound} outward · ${data.occupancy.returning} return`" description="Passenger counts" icon="i-lucide-bus" /><MetricCard label="Registration deadline" :value="data.event.registrationDeadline" :description="`Details due ${data.event.detailsDeadline || data.event.registrationDeadline}`" icon="i-lucide-calendar-clock" /></div>
      <div v-if="data.canManage && data.registrationSummary" class="mb-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard :label="data.event.registrationMode === 'public' ? 'Participants enrolled' : 'Students enrolled'" :value="String(data.registrationSummary.enrolledStudents)" :description="data.event.registrationMode === 'public' ? `${data.registrationSummary.parents} accompanying adults` : `${data.registrationSummary.internalStudents} own · ${data.registrationSummary.guestStudents} guests`" icon="i-lucide-graduation-cap" /><MetricCard label="Requests to review" :value="String(data.registrationSummary.submitted)" description="Not yet reserved or charged" icon="i-lucide-clipboard-list" /><MetricCard label="Bookings paid" :value="String(data.registrationSummary.paidBookings)" :description="`${data.registrationSummary.partPaidBookings} partly paid`" icon="i-lucide-circle-check" /><MetricCard label="Family balance due" :value="formatMinor(data.finances.outstanding)" :description="`${data.registrationSummary.pendingFeeBookings} bookings with no payment`" icon="i-lucide-wallet" /></div>
      <div class="mb-6 flex flex-wrap gap-2 border-b border-slate-200 pb-3 dark:border-slate-800"><UButton v-for="item in tabs" :key="item.value" :variant="tab === item.value ? 'solid' : 'ghost'" :color="tab === item.value ? 'primary' : 'neutral'" @click="() => { tab = item.value }">{{ item.label }}</UButton></div>
      <div v-if="showBooking" class="mb-6"><EventBookingForm :key="editingBooking?.id || 'new'" :event="data.event" :students="data.students" :initial="editingBooking" :portal="!!portal" :can-manage="data.canManage" :endpoint="endpoint" @saved="bookingSaved" @cancel="showBooking = false" /></div>
      <div v-if="tab === 'overview'" class="grid gap-6 lg:grid-cols-2"><UCard><template #header><h3 class="font-semibold">About this event</h3></template><p class="whitespace-pre-wrap">{{ data.event.description || 'Details will be shared by the organizer.' }}</p><dl class="mt-6 space-y-3 text-sm"><div v-for="price in priceLabels.filter(item => data.event.transportProvided || !['transportOut', 'transportReturn'].includes(item.key))" :key="price.key" class="flex justify-between"><dt>{{ price.label }}</dt><dd class="font-semibold">{{ formatMinor(data.event.prices[price.key]) }}</dd></div><div class="flex justify-between"><dt>Tax</dt><dd>{{ data.event.prices.taxBps / 100 }}%</dd></div></dl><p class="mt-4 text-xs text-slate-500">Optional services are charged per attendee when selected. A zero rate means no additional charge.</p></UCard><UCard><template #header><h3 class="font-semibold">Instructions and terms</h3></template><p class="whitespace-pre-wrap text-sm">{{ data.event.instructions || 'Event instructions will appear here.' }}</p><details class="mt-6"><summary class="cursor-pointer font-medium">Participation and cancellation terms</summary><p class="mt-3 whitespace-pre-wrap text-sm">{{ data.event.terms }}</p></details><p class="mt-5 text-sm text-slate-500">{{ data.event.confirmationRule === 'staff' ? 'Bookings are confirmed by the event team after details and consent are complete.' : data.event.confirmationRule === 'deposit' ? `Confirmation requires a ${formatMinor(data.event.deposit)} deposit per booking (or the full total if lower), complete details and consent.` : 'Confirmation requires full payment, complete attendee details and consent.' }}</p></UCard></div>
      <EventRegistrationRequests v-if="tab === 'requests' && data.canManage" :event="data.event" :requests="data.registrationRequests" :bookings="data.bookings" :students="data.students" :invitation="data.invitation" :summary="data.registrationSummary" :endpoint="endpoint" @changed="refresh" />
      <div v-if="tab === 'bookings'" class="space-y-4">
        <div class="flex flex-wrap justify-between gap-3"><UInput v-model="search" icon="i-lucide-search" placeholder="Search name, reference, status" aria-label="Search bookings" /><div v-if="!portal" class="flex gap-2"><UButton :href="`${endpoint}/export?kind=bookings`" external variant="outline" icon="i-lucide-download">Export bookings</UButton></div></div>
        <UCard v-for="booking in filteredBookings" :key="booking.id">
          <div class="flex flex-wrap justify-between gap-4"><div><div class="flex flex-wrap items-center gap-2"><h3 class="font-semibold">{{ booking.attendees.find((person: any) => person.type === 'student')?.name }} <span class="font-normal text-slate-500">· {{ booking.reference }}</span></h3><UBadge :color="booking.status === 'confirmed' ? 'success' : booking.status === 'cancelled' ? 'error' : 'warning'">{{ booking.status }}</UBadge><UBadge :color="booking.paymentStatus === 'paid' ? 'success' : booking.paymentStatus === 'credit_due' ? 'error' : 'warning'" variant="soft">Fees {{ booking.paymentStatus.replaceAll('_', ' ') }}</UBadge></div><p class="mt-2 text-sm">{{ booking.attendees.map((person: any) => person.name || 'Parent details pending').join(' · ') }}</p><p class="mt-1 text-sm text-slate-500">{{ data.event.registrationMode === 'public' ? `Event participant${booking.guestProfile?.dojoName && booking.guestProfile.dojoName !== 'Independent' ? ' - ' + booking.guestProfile.dojoName : ''}` : booking.guestProfile ? `Guest · ${booking.guestProfile.dojoName}, ${booking.guestProfile.state}, ${booking.guestProfile.country}` : 'Existing student' }} · {{ booking.contactName || 'Contact pending' }} {{ booking.contactPhone }}</p></div><div class="text-sm"><p>Total <strong>{{ formatMinor(booking.balance.total) }}</strong> · paid {{ formatMinor(booking.balance.paid) }}</p><p class="mt-1" :class="booking.balance.outstanding ? 'text-amber-600' : 'text-green-600'">Balance {{ formatMinor(booking.balance.outstanding) }}<span v-if="booking.balance.credit"> · Refund / credit due {{ formatMinor(booking.balance.credit) }}</span></p></div></div>
          <p v-if="booking.missing.length && booking.status !== 'cancelled'" class="mt-3 text-sm text-amber-600">Details needed: {{ booking.missing.join(', ') }}</p>
          <details v-if="booking.customAnswers?.length" class="mt-3 text-sm"><summary class="cursor-pointer text-primary">Additional registration answers</summary><p v-for="answer in booking.customAnswers" :key="answer.id" class="mt-1"><strong>{{ answer.label }}:</strong> {{ typeof answer.value === 'boolean' ? answer.value ? 'Yes' : 'No' : answer.value || 'Not answered' }}</p></details>
          <div class="mt-4 flex flex-wrap gap-2"><UButton v-if="booking.status !== 'cancelled' && !['completed', 'cancelled'].includes(data.event.status)" size="sm" variant="outline" @click="openBooking(booking)">Edit details</UButton><a :href="`${endpoint}/receipt?bookingId=${booking.id}`" target="_blank" rel="noopener" class="inline-flex items-center rounded-md px-3 py-1.5 text-sm font-medium text-primary">Booking PDF</a><template v-if="data.canManage && booking.status !== 'cancelled'"><UButton v-if="booking.balance.outstanding && booking.status !== 'waitlisted'" size="sm" variant="soft" @click="recordPayment(booking)">Record payment</UButton><UButton v-if="booking.status === 'waitlisted'" size="sm" variant="soft" :loading="busy === booking.id" @click="updateBooking(booking, { status: booking.missing.length ? 'provisional' : 'pending' })">Reserve places</UButton><UButton v-else-if="booking.status !== 'confirmed'" size="sm" color="success" variant="soft" :loading="busy === booking.id" @click="updateBooking(booking, { status: 'confirmed' })">Confirm</UButton><UButton size="sm" color="error" variant="ghost" @click="() => { cancelBookingId = cancelBookingId === booking.id ? null : booking.id }">Cancel booking</UButton></template></div>
          <form v-if="cancelBookingId === booking.id" class="mt-4 flex flex-wrap items-end gap-3 rounded-lg bg-red-50 p-3 dark:bg-red-950/20" @submit.prevent="cancelBooking(booking)"><label class="text-sm">Retained cancellation fee before tax ({{ data.event.currency }})<input v-model.number="retainedFee" type="number" min="0" step="0.01" required class="mt-1 block w-full rounded-md border border-slate-300 bg-white p-2 text-slate-900"></label><UButton type="submit" color="error" :loading="busy === booking.id">Confirm cancellation</UButton><p class="w-full text-xs">The booking is preserved. Any refundable balance must be returned and recorded separately in Finance.</p></form>
          <details v-if="bookingLedger(booking.id).length" class="mt-4 text-sm"><summary class="cursor-pointer text-slate-500">Payments and receipts</summary><div v-for="row in bookingLedger(booking.id)" :key="row.id" class="mt-2 flex flex-wrap justify-between gap-2"><span>{{ row.occurredOn }} · {{ row.kind }} · {{ formatMinor(row.amount) }}</span><a :href="`${endpoint}/receipt?transactionId=${row.id}`" target="_blank" rel="noopener" class="text-primary underline">{{ row.receiptNumber }} PDF</a></div></details>
        </UCard>
        <UCard v-if="!filteredBookings.length"><p class="py-6 text-center text-sm text-slate-500">No bookings yet. Share the invitation and registration link, then approve submitted requests.</p></UCard>
      </div>
      <div v-if="tab === 'operations'" class="space-y-5">
        <div class="flex flex-wrap gap-2"><UButton v-for="kind in exportKinds.filter(item => data.event.transportProvided || item.value !== 'transport')" :key="kind.value" :href="`${endpoint}/export?kind=${kind.value}`" external variant="outline" icon="i-lucide-download">{{ kind.label }}</UButton></div>
        <UCard><template #header><div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">Attendee manifest and check-in</h3><UInput v-model="search" placeholder="Search name or room" aria-label="Search attendees" /></div></template><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Attendee / booking</th><th>Meals</th><th>Accommodation</th><th v-if="data.event.transportProvided">Travel</th><th>Emergency / care</th><th>Check-in</th></tr></thead><tbody><tr v-for="row in attendees" :key="row.person.id"><td><p class="font-medium">{{ row.person.name || 'Name pending' }}</p><p class="text-xs text-slate-500">{{ row.person.type }} · {{ row.booking.reference }}</p></td><td>{{ row.person.meal || 'Pending' }}</td><td>{{ row.person.accommodation ? row.person.room || 'Room unassigned' : 'Not requested' }}</td><td v-if="data.event.transportProvided"><p>{{ row.person.transportOut ? `Out: ${row.person.busOut || 'unassigned'}` : 'No outward bus' }}</p><p>{{ row.person.transportReturn ? `Return: ${row.person.busReturn || 'unassigned'}` : 'No return bus' }}</p></td><td><details><summary class="cursor-pointer text-primary">View contact / needs</summary><p class="mt-2">{{ row.booking.emergencyName }} {{ row.booking.emergencyPhone || row.booking.contactPhone }}</p><p class="mt-1 whitespace-pre-wrap">{{ row.person.medicalNotes || 'No requirements supplied' }}</p></details></td><td><UButton size="xs" :color="row.person.checkedInAt ? 'success' : 'neutral'" variant="soft" :disabled="row.booking.status !== 'confirmed'" :loading="busy === row.booking.id" @click="updateBooking(row.booking, { checkInId: row.person.id, checkIn: !row.person.checkedInAt })">{{ row.person.checkedInAt ? 'Undo check-in' : 'Check in' }}</UButton></td></tr></tbody></table><p v-if="!attendees.length" class="py-6 text-center text-slate-500">No reserved attendees match this search.</p></div></UCard>
      </div>
      <EventFinancePanel v-if="tab === 'finance' && data.canManage" :event="data.event" :finances="data.finances" :bookings="data.bookings" :costs="data.costs" :ledger="data.ledger" :endpoint="endpoint" :initial-booking-id="paymentBookingId" @changed="refresh" />
      <UCard v-if="tab === 'activity' && data.canManage"><template #header><h3 class="font-semibold">Recent activity</h3></template><div v-for="entry in data.activity" :key="entry.id" class="border-b border-slate-100 py-3 last:border-0 dark:border-slate-800"><p class="text-sm font-medium">{{ entry.action }} · {{ entry.details }}</p><p class="mt-1 text-xs text-slate-500">{{ entry.actor }} · {{ new Date(entry.createdAt).toLocaleString() }}</p></div></UCard>
    </template>
  </div>
</template>
<script setup lang="ts">
const props = defineProps<{ portal?: boolean }>()
const route = useRoute(); const toast = useToast()
const endpoint = `${props.portal ? '/api/portal' : '/api'}/events/${route.params.id}`
const { data, pending, error, refresh } = await useFetch<any>(endpoint)
const { formatMinor } = useMoney(() => data.value?.event.currency)
const tab = ref(props.portal ? 'bookings' : 'overview'); const editingEvent = ref(false); const showBooking = ref(false); const editingBooking = ref<any>(null); const search = ref(''); const busy = ref<number | null>(null); const cancelBookingId = ref<number | null>(null); const retainedFee = ref(0)
const paymentBookingId = ref<number | null>(null)
const deletingEvent = ref(false)
const tabs = computed(() => [{ value: 'overview', label: 'Overview' }, ...(data.value?.canManage ? [{ value: 'requests', label: `Public requests (${(data.value.registrationRequests || []).filter((item: any) => item.status === 'submitted').length})` }] : []), { value: 'bookings', label: props.portal ? 'My bookings' : 'Bookings' }, ...(!props.portal ? [{ value: 'operations', label: 'Operations' }] : []), ...(data.value?.canManage ? [{ value: 'finance', label: 'Finance' }, { value: 'activity', label: 'Activity' }] : [])])
const priceLabels = [{ key: 'student', label: 'Student base rate' }, { key: 'parent', label: 'Parent base rate' }, { key: 'transportOut', label: 'Outward transport' }, { key: 'transportReturn', label: 'Return transport' }, { key: 'accommodation', label: 'Accommodation' }]
const exportKinds = [{ value: 'attendees', label: 'Attendees' }, { value: 'transport', label: 'Transport' }, { value: 'accommodation', label: 'Accommodation' }, { value: 'meals', label: 'Meals' }, { value: 'emergency', label: 'Emergency contacts' }]
const canRegister = computed(() => data.value?.event.registrationMode !== 'public' && data.value?.event.status === 'open' && data.value.event.registrationDeadline >= new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' }) && (!props.portal || !data.value.bookings.some((booking: any) => booking.status !== 'cancelled')))
const filteredBookings = computed(() => (data.value?.bookings || []).filter((booking: any) => `${booking.reference} ${booking.status} ${booking.attendees.map((person: any) => person.name).join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
const attendees = computed(() => (data.value?.bookings || []).filter((booking: any) => ['provisional', 'pending', 'confirmed'].includes(booking.status)).flatMap((booking: any) => booking.attendees.map((person: any) => ({ person, booking }))).filter((row: any) => `${row.person.name} ${row.person.room} ${row.person.busOut} ${row.person.busReturn}`.toLowerCase().includes(search.value.toLowerCase())))
function bookingLedger(id: number) { return (data.value?.ledger || []).filter((row: any) => row.bookingId === id) }
function openBooking(booking?: any) { editingBooking.value = booking || null; showBooking.value = true; tab.value = 'bookings' }
function recordPayment(booking: any) { paymentBookingId.value = booking.id; tab.value = 'finance' }
async function bookingSaved() { showBooking.value = false; editingBooking.value = null; await refresh(); toast.add({ title: 'Booking saved', color: 'success' }) }
async function eventSaved() { editingEvent.value = false; await refresh(); toast.add({ title: 'Event updated', color: 'success' }) }
async function deleteEvent() { if (!confirm('Permanently delete this unused event?')) return; deletingEvent.value = true; try { await $fetch(endpoint, { method: 'DELETE' }); await navigateTo('/events'); toast.add({ title: 'Event deleted', color: 'success' }) } catch (err: any) { toast.add({ title: err.data?.statusMessage || err.message, color: 'error' }) } finally { deletingEvent.value = false } }
async function updateBooking(booking: any, body: any) { busy.value = booking.id; try { await $fetch(`${endpoint}/bookings/${booking.id}`, { method: 'PATCH', body: { version: booking.version, ...body } }); await refresh(); toast.add({ title: 'Booking updated', color: 'success' }) } catch (err: any) { toast.add({ title: err.data?.statusMessage || err.message, color: 'error' }) } finally { busy.value = null } }
async function cancelBooking(booking: any) { await updateBooking(booking, { status: 'cancelled', cancellationFee: Math.round(retainedFee.value * 100) }); cancelBookingId.value = null; retainedFee.value = 0 }
</script>
<style scoped>th, td { padding:.8rem .6rem; border-bottom:1px solid var(--ui-border); vertical-align:top; }</style>
